package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestLoadConfigAppliesSafeDefaultsAndReadsProtectedToken(t *testing.T) {
	directory := t.TempDir()
	tokenPath := filepath.Join(directory, "token")
	if err := os.WriteFile(tokenPath, []byte("secret-token\n"), 0o640); err != nil {
		t.Fatal(err)
	}
	configPath := filepath.Join(directory, "config.yaml")
	configText := "gateway_url: https://gateway.example/api/v1/status/events\ntoken_file: " + tokenPath + "\nled: A2\n"
	if err := os.WriteFile(configPath, []byte(configText), 0o600); err != nil {
		t.Fatal(err)
	}

	config, token, err := loadConfig(configPath)
	if err != nil {
		t.Fatal(err)
	}
	if token != "secret-token" {
		t.Fatalf("token=%q", token)
	}
	if config.LED != "A2" || config.ActivityHold != 750*time.Millisecond || config.StreamTimeout != 45*time.Second {
		t.Fatalf("unexpected defaults: %+v", config)
	}
}

func TestLoadConfigRejectsUnsafeInput(t *testing.T) {
	directory := t.TempDir()
	secureToken := filepath.Join(directory, "secure-token")
	if err := os.WriteFile(secureToken, []byte("token"), 0o600); err != nil {
		t.Fatal(err)
	}
	tests := []struct {
		name   string
		config string
		setup  func() string
		want   string
	}{
		{name: "HTTP endpoint", config: "gateway_url: http://gateway/api/v1/status/events\ntoken_file: " + secureToken + "\n", want: "https"},
		{name: "credentials in URL", config: "gateway_url: https://user:pass@gateway/api/v1/status/events\ntoken_file: " + secureToken + "\n", want: "credentials"},
		{name: "wrong endpoint path", config: "gateway_url: https://gateway/api/v1/status\ntoken_file: " + secureToken + "\n", want: "/api/v1/status/events"},
		{name: "unknown field", config: "gateway_url: https://gateway/api/v1/status/events\ntoken_file: " + secureToken + "\nextra: true\n", want: "field extra"},
		{name: "short timeout", config: "gateway_url: https://gateway/api/v1/status/events\ntoken_file: " + secureToken + "\nstream_timeout: 15s\n", want: "greater than"},
		{name: "world-readable token", setup: func() string {
			path := filepath.Join(directory, "open-token")
			if err := os.WriteFile(path, []byte("token"), 0o644); err != nil {
				t.Fatal(err)
			}
			return path
		}, want: "permissions"},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			configText := test.config
			if test.setup != nil {
				configText = "gateway_url: https://gateway/api/v1/status/events\ntoken_file: " + test.setup() + "\n"
			}
			path := filepath.Join(directory, strings.ReplaceAll(test.name, " ", "-")+".yaml")
			if err := os.WriteFile(path, []byte(configText), 0o600); err != nil {
				t.Fatal(err)
			}
			_, _, err := loadConfig(path)
			if err == nil || !strings.Contains(err.Error(), test.want) {
				t.Fatalf("error=%v, want substring %q", err, test.want)
			}
		})
	}
}
